@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models

<nav class="settings-sidebar">
    <h5 class="sidebar-title">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <button class="nav-link @(ActiveSection == section ? "active" : "")"
                        @onclick="() => OnSectionChanged.InvokeAsync(section)">
                    <span class="section-icon">@GetIcon(section)</span>
                    @section
                </button>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter, EditorRequired] public string ActiveSection { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    padding: 1rem 0;
    min-width: 200px;
    border-right: 1px solid #dee2e6;
    height: 100%;
}

.sidebar-title {
    padding: 0 1rem 0.75rem;
    margin-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
    font-weight: 600;
    color: #333;
}

.nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    color: #555;
    font-size: 0.95rem;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
}

.nav-link:hover {
    background-color: #f0f0f0;
    color: #333;
}

.nav-link.active {
    background-color: #e8f0fe;
    color: #1a73e8;
    border-left-color: #1a73e8;
    font-weight: 600;
}

.section-icon {
    font-size: 1.1rem;
}

@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models

<div class="profile-section">
    <h4>Profile Settings</h4>

    <div class="avatar-area">
        @if (!string.IsNullOrEmpty(avatarUrl))
        {
            <img src="@avatarUrl" alt="Avatar" class="avatar-preview" />
        }
        else
        {
            <div class="avatar-placeholder">No Avatar</div>
        }
        <div class="avatar-url-display">
            <label class="form-label">Avatar URL</label>
            <input type="url" class="form-control" value="@avatarUrl"
                   @oninput="e => avatarUrl = e.Value?.ToString() ?? string.Empty" />
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Display Name</label>
        <input type="text" class="form-control" @bind="displayName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <input type="email" class="form-control" @bind="email" />
    </div>

    <div class="mb-3">
        <label class="form-label">Bio</label>
        <textarea class="form-control" rows="4" @bind="bio"></textarea>
    </div>

    <div class="button-group">
        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (showSuccessMessage)
    {
        <div class="alert alert-success mt-3 fade-in" role="alert">
            ✅ Profile saved successfully!
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";
    private bool isSaving;
    private bool showSuccessMessage;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        displayName = Profile.DisplayName;
        email = Profile.Email;
        avatarUrl = Profile.AvatarUrl;
        bio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccessMessage = false;

        var updated = new UserProfile(displayName, email, avatarUrl, bio);
        await OnSave.InvokeAsync(updated);

        isSaving = false;
        showSuccessMessage = true;

        _ = DismissMessageAfterDelay();
    }

    private async Task DismissMessageAfterDelay()
    {
        await Task.Delay(3000);
        showSuccessMessage = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        LoadFromProfile();
        showSuccessMessage = false;
    }
}

.profile-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.avatar-area {
    display: flex;
    align-items: flex-start;
    gap: 1.5rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.avatar-preview {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #dee2e6;
}

.avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: #dee2e6;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    color: #888;
}

.avatar-url-display {
    flex: 1;
}

.button-group {
    display: flex;
    gap: 0.75rem;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models

<div class="notifications-section">
    <h4>Notification Preferences</h4>

    <div class="toggle-group">
        <div class="toggle-item">
            <div>
                <strong>Email Notifications</strong>
                <p class="text-muted mb-0">Receive notifications via email</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@emailNotifications"
                       @onchange="e => emailNotifications = (bool)(e.Value ?? false)" />
            </div>
        </div>

        <div class="toggle-item">
            <div>
                <strong>Push Notifications</strong>
                <p class="text-muted mb-0">Receive push notifications in your browser</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@pushNotifications"
                       @onchange="e => pushNotifications = (bool)(e.Value ?? false)" />
            </div>
        </div>

        <div class="toggle-item">
            <div>
                <strong>Weekly Digest</strong>
                <p class="text-muted mb-0">Get a weekly summary of activity</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@weeklyDigest"
                       @onchange="e => weeklyDigest = (bool)(e.Value ?? false)" />
            </div>
        </div>
    </div>

    <div class="channels-section">
        <h6>Muted Channels</h6>
        <p class="text-muted">Select channels to mute notifications from:</p>
        <div class="channel-list">
            @foreach (var channel in AvailableChannels)
            {
                var isMuted = mutedChannels.Contains(channel);
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@isMuted"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
        @if (isSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>

    @if (showSuccess)
    {
        <div class="alert alert-success mt-3 fade-in" role="alert">
            ✅ Notification preferences saved!
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AvailableChannels { get; set; } = ["General", "Announcements", "Engineering", "Design", "Marketing", "Support"];

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isSaving;
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;

        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);

        isSaving = false;
        showSuccess = true;

        _ = DismissAfterDelay();
    }

    private async Task DismissAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.notifications-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.toggle-group {
    margin-bottom: 1.5rem;
}

.toggle-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    margin-bottom: 0.5rem;
}

.toggle-item p {
    font-size: 0.85rem;
}

.channels-section {
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 0.5rem;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

.change-password-panel {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    margin-bottom: 1.5rem;
}

.panel-toggle {
    width: 100%;
    padding: 0.75rem 1rem;
