@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models

<div class="session-table-container">
    <h6>Active Sessions</h6>
    <table class="table table-hover">
        <thead>
            <tr>
                <th>Device</th>
                <th>Location</th>
                <th>Last Active</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var session in Sessions)
            {
                <tr>
                    <td>@session.Device</td>
                    <td>@session.Location</td>
                    <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                    <td>
                        @if (session.Id != CurrentSessionId)
                        {
                            @if (confirmingSessionId == session.Id)
                            {
                                <div class="confirm-revoke">
                                    <span class="text-danger me-2">Revoke this session?</span>
                                    <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session.Id)"
                                            disabled="@isRevoking">
                                        Yes
                                    </button>
                                    <button class="btn btn-outline-secondary btn-sm" @onclick="CancelRevoke">
                                        No
                                    </button>
                                </div>
                            }
                            else
                            {
                                <button class="btn btn-outline-danger btn-sm"
                                        @onclick="() => confirmingSessionId = session.Id">
                                    Revoke
                                </button>
                            }
                        }
                        else
                        {
                            <span class="badge bg-success">Current</span>
                        }
                    </td>
                </tr>
            }
        </tbody>
    </table>
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<string> OnRevoke { get; set; }
    [Parameter] public string? CurrentSessionId { get; set; }

    private string? confirmingSessionId;
    private bool isRevoking;

    private async Task ConfirmRevoke(string sessionId)
    {
        isRevoking = true;
        await OnRevoke.InvokeAsync(sessionId);
        confirmingSessionId = null;
        isRevoking = false;
    }

    private void CancelRevoke()
    {
        confirmingSessionId = null;
    }
}

.session-table-container h6 {
    margin-bottom: 1rem;
    font-weight: 600;
}

.confirm-revoke {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    white-space: nowrap;
}

@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models
@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Components.Settings

<div class="security-section">
    <h4>Security Settings</h4>

    <ChangePasswordPanel OnChangePassword="OnChangePassword" />

    <div class="tfa-section">
        <div class="toggle-item">
            <div>
                <strong>Two-Factor Authentication</strong>
                <p class="text-muted mb-0">
                    Add an extra layer of security to your account
                </p>
            </div>
            <div class="d-flex align-items-center gap-2">
                <span class="badge @(twoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
                <div class="form-check form-switch mb-0">
                    <input class="form-check-input" type="checkbox" role="switch"
                           checked="@twoFactorEnabled"
                           @onchange="e => twoFactorEnabled = (bool)(e.Value ?? false)" />
                </div>
            </div>
        </div>

        @if (Security.LastPasswordChange.HasValue)
        {
            <p class="text-muted mt-2">
                Last password change: @Security.LastPasswordChange.Value.ToString("MMMM d, yyyy")
            </p>
        }
    </div>

    <SessionTable Sessions="Security.Sessions"
                  CurrentSessionId="@Security.Sessions.FirstOrDefault()?.Id"
                  OnRevoke="OnRevoke" />
</div>

@code {
    [Parameter, EditorRequired] public SecuritySettings Security { get; set; } = default!;
    [Parameter, EditorRequired]
    public EventCallback<(string CurrentPassword, string NewPassword)> OnChangePassword { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnRevoke { get; set; }

    private bool twoFactorEnabled;

    protected override void OnParametersSet()
    {
        twoFactorEnabled = Security.TwoFactorEnabled;
    }
}

.security-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.tfa-section {
    margin-bottom: 1.5rem;
}

.toggle-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
}

.toggle-item p {
    font-size: 0.85rem;
}

@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models

<div class="appearance-section">
    <h4>Appearance Settings</h4>

    <div class="setting-group">
        <h6>Theme</h6>
        <div class="btn-group" role="group">
            @foreach (var t in new[] { "Light", "Dark", "System" })
            {
                <input type="radio" class="btn-check" name="theme"
                       id="@($"theme-{t}")" value="@t"
                       checked="@(theme == t)"
                       @onchange="() => theme = t" />
                <label class="btn btn-outline-primary" for="@($"theme-{t}")">@t</label>
            }
        </div>
    </div>

    <div class="setting-group">
        <h6>Font Size</h6>
        <div class="btn-group" role="group">
            @foreach (var s in new[] { "Small", "Medium", "Large" })
            {
                <input type="radio" class="btn-check" name="fontSize"
                       id="@($"fs-{s}")" value="@s"
                       checked="@(fontSize == s)"
                       @onchange="() => fontSize = s" />
                <label class="btn btn-outline-primary" for="@($"fs-{s}")">@s</label>
            }
        </div>
    </div>

    <div class="setting-group">
        <h6>Language</h6>
        <select class="form-select language-select" @bind="language">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
        </select>
    </div>

    <div class="setting-group">
