toolArgs.file_text:
@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models

<div class="notifications-section">
    <h4>Notification Preferences</h4>

    <div class="toggle-group">
        <div class="toggle-item">
            <div>
                <strong>Email Notifications</strong>
                <p class="text-muted mb-0">Receive notifications via email</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@emailNotifications"
                       @onchange="e => emailNotifications = (bool)(e.Value ?? false)" />
            </div>
        </div>

        <div class="toggle-item">
            <div>
                <strong>Push Notifications</strong>
                <p class="text-muted mb-0">Receive push notifications in your browser</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@pushNotifications"
                       @onchange="e => pushNotifications = (bool)(e.Value ?? false)" />
            </div>
        </div>

        <div class="toggle-item">
            <div>
                <strong>Weekly Digest</strong>
                <p class="text-muted mb-0">Get a weekly summary of activity</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@weeklyDigest"
                       @onchange="e => weeklyDigest = (bool)(e.Value ?? false)" />
            </div>
        </div>
    </div>

    <div class="channels-section">
        <h6>Muted Channels</h6>
        <p class="text-muted">Select channels to mute notifications from:</p>
        <div class="channel-list">
            @foreach (var channel in AvailableChannels)
            {
                var isMuted = mutedChannels.Contains(channel);
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@isMuted"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
        @if (isSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>

    @if (showSuccess)
    {
        <div class="alert alert-success mt-3 fade-in" role="alert">
            ✅ Notification preferences saved!
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<NotificationPrefs> OnSave { get; set; }
    [Parameter] public List<string> AvailableChannels { get; set; } = ["General", "Announcements", "Engineering", "Design", "Marketing", "Support"];

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isSaving;
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;

        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);

        isSaving = false;
        showSuccess = true;

        _ = DismissAfterDelay();
    }

    private async Task DismissAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

