toolArgs.file_text:
@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models

<div class="appearance-section">
    <h4>Appearance Settings</h4>

    <div class="setting-group">
        <h6>Theme</h6>
        <div class="btn-group" role="group">
            @foreach (var t in new[] { "Light", "Dark", "System" })
            {
                <input type="radio" class="btn-check" name="theme"
                       id="@($"theme-{t}")" value="@t"
                       checked="@(theme == t)"
                       @onchange="() => theme = t" />
                <label class="btn btn-outline-primary" for="@($"theme-{t}")">@t</label>
            }
        </div>
    </div>

    <div class="setting-group">
        <h6>Font Size</h6>
        <div class="btn-group" role="group">
            @foreach (var s in new[] { "Small", "Medium", "Large" })
            {
                <input type="radio" class="btn-check" name="fontSize"
                       id="@($"fs-{s}")" value="@s"
                       checked="@(fontSize == s)"
                       @onchange="() => fontSize = s" />
                <label class="btn btn-outline-primary" for="@($"fs-{s}")">@s</label>
            }
        </div>
    </div>

    <div class="setting-group">
        <h6>Language</h6>
        <select class="form-select language-select" @bind="language">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
        </select>
    </div>

    <div class="setting-group">
        <div class="toggle-item">
            <div>
                <strong>Compact Mode</strong>
                <p class="text-muted mb-0">Reduce spacing and padding throughout the interface</p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch"
                       checked="@compactMode"
                       @onchange="e => compactMode = (bool)(e.Value ?? false)" />
            </div>
        </div>
    </div>

    <div class="preview-area">
        <h6>Preview</h6>
        <div class="preview-box @GetPreviewClasses()">
            <div class="preview-header">Sample Header</div>
            <p class="preview-text">
                This is a preview of how your content will look with the selected
                appearance settings. The theme, font size, and compact mode are
                reflected here.
            </p>
            <button class="preview-button">Sample Button</button>
        </div>
    </div>

    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
        @if (isSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save
    </button>

    @if (showSuccess)
    {
        <div class="alert alert-success mt-3 fade-in" role="alert">
            ✅ Appearance settings saved!
        </div>
    }
