@code {
    [Parameter, EditorRequired] public AppearanceSettings Appearance { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private bool isSaving;
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            theme = Appearance.Theme;
            fontSize = Appearance.FontSize;
            language = Appearance.Language;
            compactMode = Appearance.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{theme.ToLowerInvariant()} font-{fontSize.ToLowerInvariant()}";
        if (compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        showSuccess = false;

        var updated = new AppearanceSettings(theme, fontSize, language, compactMode);
        await OnSave.InvokeAsync(updated);

        isSaving = false;
        showSuccess = true;

        _ = DismissAfterDelay();
    }

    private async Task DismissAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

