toolArgs.file_text:
.appearance-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.setting-group {
    margin-bottom: 1.5rem;
}

.setting-group h6 {
    margin-bottom: 0.5rem;
    font-weight: 600;
}

.language-select {
    max-width: 250px;
}

.toggle-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border: 1px solid #dee2e6;
    border-radius: 6px;
}

.toggle-item p {
    font-size: 0.85rem;
}

.preview-area {
    margin-bottom: 1.5rem;
}

.preview-area h6 {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

.preview-box {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.5rem;
    transition: all 0.3s ease;
}

/* Theme variants */
.preview-box.theme-light {
    background: #ffffff;
    color: #333333;
}

.preview-box.theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
}

.preview-box.theme-system {
    background: #f5f5f5;
    color: #444444;
}

/* Font size variants */
.preview-box.font-small {
    font-size: 0.8rem;
}

.preview-box.font-medium {
    font-size: 1rem;
}

.preview-box.font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-box.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    font-weight: 700;
    font-size: 1.2em;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
    opacity: 0.85;
}

.preview-button {
    padding: 0.4rem 1rem;
    border: 1px solid currentColor;
    background: transparent;
    color: inherit;
    border-radius: 4px;
    cursor: default;
}

.preview-box.compact .preview-header {
    margin-bottom: 0.25rem;
}

.preview-box.compact .preview-text {
    margin-bottom: 0.4rem;
}

.preview-box.compact .preview-button {
    padding: 0.2rem 0.6rem;
}

.theme-dark .preview-button {
    border-color: #888;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-5px); }
    to { opacity: 1; transform: translateY(0); }
}

