arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Models
@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Services
@using sv_a21545ce108b4e2bbb6b1c83fd2846b2.Components.Settings
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection"
                     OnSectionChanged="section => activeSection = section" />

    <div class="settings-content">
        @if (isLoading)
        {
            <div class="loading-state">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
                <p class="mt-2 text-muted">Loading settings…</p>
            </div>
        }
        else if (loadError is not null)
        {
            <div class="alert alert-danger" role="alert">
                Failed to load settings: @loadError
            </div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection Profile="profile!" OnSave="SaveProfileAsync" />
                    break;

                case "Notifications":
                    <NotificationsSection Prefs="notificationPrefs!" OnSave="SaveNotificationPrefsAsync" />
                    break;

                case "Security":
                    <SecuritySection Security="securitySettings!"
                                     OnChangePassword="ChangePasswordAsync"
                                     OnRevoke="RevokeSessionAsync" />
                    break;

                case "Appearance":
                    <AppearanceSection Appearance="appearanceSettings!" OnSave="SaveAppearanceAsync" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? loadError;

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var profileTask = SettingsService.GetProfileAsync();
            var notifTask = SettingsService.GetNotificationPrefsAsync();
            var securityTask = SettingsService.GetSecuritySettingsAsync();
            var appearanceTask = SettingsService.GetAppearanceAsync();

            await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

            profile = profileTask.Result;
            notificationPrefs = notifTask.Result;
            securitySettings = securityTask.Result;
            appearanceSettings = appearanceTask.Result;
        }
        catch (Exception ex)
        {
            loadError = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationPrefsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task ChangePasswordAsync((string CurrentPassword, string NewPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.CurrentPassword, args.NewPassword);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

